mapper.select:
SELECT m.user_id, u.name AS user_name, m.farm_id, f.name AS farm_name, m.role FROM t_farm_member m JOIN t_farm f ON f.id = m.farm_id JOIN t_user u ON u.id = m.user_id AND u.status = 'NORMAL' WHERE m.status = 'ACTIVE' AND m.active_flag = 1 AND f.deleted = 0 AND f.audit_status = 'APPROVED' AND f.disabled = 0 AND f.frozen = 0
AND m.role IN #{role}
AND CONCAT(LEFT(f.adcode, 2), '0000') IN #{code}
AND f.main_category_id IN #{categoryId}
ORDER BY m.user_id, m.farm_id
